#include <iostream>
#include <vector>
using namespace std;
​
// 素数筛
vector<bool> sieve(int n) {
    vector<bool> isPrime(n + 1, true);
    isPrime[0] = isPrime[1] = false;
    for (int i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j+=i) {
                isPrime[j] = false;
            }
        }
    }
    return isPrime;
}
​
// 尝试匹配
bool canMatch(vector<int>& ans, int index, vector<bool>& isPrime, vector<int>& match, vector<bool>& visited) {
    int n = ans.size();
    for (int i = 0; i < n; i++) {
        // 自己不能和自己匹配
        if (index == i) {
            continue;
        }
        // 不是素数
        if (!isPrime[ans[index] + ans[i]]) {
            continue;
        }
        // 重复访问
        if (visited[i]) {
            continue;
        }
​
        visited[i] = true;
        // 该元素未进行匹配 或者 与该元素的匹配的元素能找到替代品
        if (match[i] == -1 || canMatch(ans, match[i], isPrime, match, visited)) {
            match[i] = index;
            return true;
        }
    }
    return false;
}
​
​
int main() {
    int n;
    cin >> n;
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        cin >> ans[i];
    }
    vector<bool> isPrime = sieve(60000);
    vector<int> match(n, -1);

    for (int i = 0; i < n; i++) {
        vector<bool> visited(n, false);
        canMatch(ans, i, isPrime, match, visited);
    }
​
    int res = 0;
    // 统计可以匹配的元素数量
    for (int i = 0; i < n; i++) {
        if (match[i] != -1) {
            res++;
        }
    }
    // 两个元素组成一队
    cout << res / 2;
    return 0;
}
