            }
        }
    }
    return isPrime;
}
​
// 尝试匹配
function canMatch(ans, index, isPrime, match, visited) {
    const n = ans.length;
    for (let i = 0; i < n; i++) {
        // 自己不能和自己匹配
        if (index === i) continue;
        // 不是素数
        if (!isPrime[ans[index] + ans[i]]) continue;
        // 重复访问
        if (visited[i]) continue;
​
        visited[i] = true;
        // 未匹配 或者原匹配对象可以换人
        if (match[i] === -1 || canMatch(ans, match[i], isPrime, match, visited)) {
            match[i] = index;
            return true;
        }
    }
    return false;
