package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 素数筛
func sieve(n int) []bool {
    isPrime := make([]bool, n+1)
    for i := 2; i <= n; i++ {
        isPrime[i] = true
    }
    for i := 2; i*i <= n; i++ {
        if isPrime[i] {
            for j := i * i; j <= n; j += i {
                isPrime[j] = false
            }
        }
    }
    return isPrime
}
​
// 尝试匹配
func canMatch(ans []int, index int, isPrime []bool, match []int, visited []bool) bool {
    n := len(ans)
    for i := 0; i < n; i++ {
        // 自己不能和自己匹配
        if index == i {
            continue
        }
        // 不是素数
        if !isPrime[ans[index]+ans[i]] {
            continue
        }
        // 重复访问 防止出现死循环
        if visited[i] {
            continue
        }
        visited[i] = true
        // 未匹配 或者可以替换
        if match[i] == -1 || canMatch(ans, match[i], isPrime, match, visited) {
            match[i] = index
            return true
        }
    }
    return false
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    var n int
    fmt.Fscan(reader, &n)
​
    line, _ := reader.ReadString('\n')
    if strings.TrimSpace(line) == "" {
        line, _ = reader.ReadString('\n')
    }
    strs := strings.Fields(line)
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        ans[i], _ = strconv.Atoi(strs[i])
    }
​
    isPrime := sieve(60000)
    match := make([]int, n)
    for i := range match {
        match[i] = -1
    }
​
    for i := 0; i < n; i++ {
        visited := make([]bool, n)
        canMatch(ans, i, isPrime, match, visited)
    }
​
    res := 0
    for _, v := range match {
        if v != -1 {
            res++
        }
    }
    fmt.Println(res / 2)
}
